  if(page==='trust:dust')return screen(env,id,'Методология и учёт пыли',currentFAQ[4][2],[[button('История операций','dust:history'),button('Условия','stars:terms')]],'trust');
  const trust={
    forecast:"В западной астрологии солнечный знак рассматривается через тропический зодиак, стихии, модальности и планетарных управителей. Это традиционный понятийный аппарат, а не описание текущих астрономических измерений.\n\nВ Астре готовые редакционные темы выбираются детерминированно по знаку и московской дате. Число дня — hash(sign + day) % 9 + 1: символический индекс 1–9, не цифровой корень даты и не число жизненного пути.\n\nЭфемериды, реальные транзиты и натальные аспекты в текущем режиме не рассчитываются. Пояснения — в FAQ.",
    tarot:"Тарологический корпус включает 22 Старших аркана с прямыми и перевёрнутыми трактовками. Карта дня фиксируется по профилю и московской дате. Ситуационный расклад содержит три разные случайно выбранные карты; позиции задают порядок чтения.\n\nГотовый текст записывается в D1 вместе с операцией оплаты. Повторная выдача читает сохранённую запись и не создаёт нового списания. Состав колоды, положение аркана и контекст позиции — разные уровни метода; Младшие арканы пока не подключены.",
    dust:"Журнал начислений и списаний в D1 отражает каждое изменение баланса. SQL-триггеры проводят операцию и запись журнала атомарно; ключи идемпотентности связывают повторные запросы с уже созданным заказом.\n\nНачальный баланс: 2 ✨; день: +1; реферал: +5; канал: +5. Три карты: 3 ✨. Пыль не выводится в деньги. При сбое передачи сохранённый результат доступен повторно; внешний Telegram может продублировать сообщение без нового списания.",
    future:"Портрет и совместимость требуют отдельных правил сопоставления исходных данных. Натальные дома, Асцендент, планетарные аспекты и лунная фаза требуют проверенного вычислительного модуля с эфемеридами и учётом времени. Эти функции сейчас недоступны.\n\nПолная колода, коллекции и магазин Stars остаются в разработке. Плата за них не взимается; заявленных сроков открытия нет.",
  };
  if(page.startsWith('trust:') && Object.hasOwn(trust,page.slice(6))) return screen(env,id,"Основания метода",trust[page.slice(6)],[],'trust');
  if(page==='team') return screen(env,id,"Отделы и консультанты","Gideon Vale — куратор астрологических соответствий, тропического зодиака и интерпретационных систем.\nPercival North — специалист по планетарным циклам и методологии прогнозов.\nThalia Wren — таролог, специалист по Старшим арканам, позициям и композиции раскладов.\n6th Registry — отдел календарных регламентов и нумерологической классификации.\n\nElias Voss — инженер программной архитектуры и информационных систем: протоколы Telegram, хранение результатов и согласованность данных.\nM. Ejaculatum — анонимный консультант по астрологии, нумерологии и сравнительной эзотерике.",[],'about');
  if(page==='faq') return screen(env,id,"Вопросы о методах и работе сервиса","Краткие сведения. Откройте вопрос для подробного разбора.\n\n"+currentFAQ.map((f,i)=>`${i+1}. ${f[0]}\n${f[1]}`).join('\n\n'),currentFAQ.map((f,i)=>[button(f[0],`faq:${i}:more`)]),'about');
  const faqMatch=/^faq:(\d{1,2})(:more)?$/.exec(page);
  if(faqMatch && FAQ[Number(faqMatch[1])]) {
    const n=Number(faqMatch[1]),item=currentFAQ[n];
    return screen(env,id,item[0],faqMatch[2]?item[2]:item[1],faqMatch[2]?[]:[[button('Подробнее',`faq:${n}:more`)]],'faq');
  }
  if(page==='rules') return screen(env,id,"Правила и данные","Астрологическая, тарологическая и нумерологическая трактовка не является гарантией события или профессиональным заключением о здоровье, праве либо инвестициях. Расчёты небесных координат следует отличать от символической интерпретации. Текущий набор методов описан в FAQ.\n\nЦена относится к доступу к материалу. Скрытых подписок нет, разрабатываемые услуги не продаются.\n\n/privacy — состав сохраняемых данных; /delete удаляет обычные данные профиля. Оплаченные доказательства и незавершённые долги сохраняются по /privacy и /terms для поддержки и возвратов. Сообщения Telegram и резервные копии управляются отдельно; уже начатую отправку отозвать нельзя.",[[button("Состав данных",'privacy')]],'about');
  if(page==='privacy') return incoming(shellEnv(env,'rules'),{from:{id},chat:{type:'private'},text:'/privacy'},updateId);
