  if(page==='forecast') return forecastMenu(env,id);
  if(page==='forecast:read') return sendFreeForecast(env,id,u.zodiac);
  const datedForecast03=/^forecast:(offer|owned):(\d{4}-\d{2}-\d{2})$/.exec(page);
  if(datedForecast03)return forecastExtended(env,id,u,datedForecast03[1]==='owned'?'repeat':'confirm',datedForecast03[2]);
  if(page==='forecast:future'||page==='forecast:extended') return forecastExtended(env,id,u,'confirm');
  if(page==='forecast:repeat') return forecastExtended(env,id,u,'repeat');
  const forecastPay=/^forecast:pay:(\d{4}-\d{2}-\d{2})$/.exec(page);
  if(forecastPay) return forecastExtended(env,id,u,'pay',forecastPay[1]);
  if(page==='dust'||page==='dossier:economy'||page==='dust:activity'||page==='dossier:activity'||page==='dust:history'||page==='dossier:history'||page.startsWith('history:')) return economyRoute(env,id,u,page);
  if(page==='self') return screen(env,id,'🪞 Познай себя',"Символический портрет, совместимость и подбор соответствий находятся в разработке. Их методика потребует отдельных исходных данных и правил сопоставления.\n\nСейчас раздел не проводит анкетирование, не сохраняет новые личные сведения и не списывает пыль.",[]);
  if(page==='dossier') return screen(env,id,'🗂 Досье',`${zodiacName(u.zodiac)}\nБаланс: ${u.balance} ✨\nРассылка: ${u.notifications_enabled?'включена':'выключена'}\nДата: ${dayMSK()} · Europe/Moscow\n\nЗдесь показаны сохранённые настройки профиля. Активные дни и история пыли доступны в экономическом досье. Натальная карта и коллекции ещё не подключены.`,[
    [button("Экономическое досье",'dossier:economy')],[button("История операций",'dossier:history')],[button("Рассылка",'notifications')],[button('Последний расклад','tarot:last')],[button("Состав данных",'privacy')]]);
  if(page==='dust:shop') return screen(env,id,"Магазин Stars","Оплата через Telegram Stars не подключена. Сервис не выставляет счета и не принимает платежи. Действующие способы начисления пыли перечислены в предыдущем разделе.",[],'dust');
  if(page==='gift') return bonus(scoped,id);
  if(page==='invite') return invite(scoped,id);
  if(page==='channel') return channelMenu(scoped,id);
  if(page==='notifications') return screen(env,id,"Утренний прогноз",`Рассылка: ${u.notifications_enabled?'включена':'выключена'}. Дневной прогноз можно открыть вручную независимо от настройки.`,[[button("Изменить настройку",'notifications:toggle')]],'dossier');
  if(page==='notifications:toggle') return incoming(shellEnv(env,'notifications'),{from:{id},chat:{type:'private'},text:'🔔 Рассылка'},updateId);
  if(page==='tarot') return screen(env,id,'🃏 Таро',"Трактовки 22 Старших арканов. В раскладе различаются позиции карт, прямое и перевёрнутое положение.\n\nКарта дня бесплатна; ситуационный расклад на три карты — 5 ✨. Сохранённый результат можно открыть повторно без оплаты.",[
    [{text:'Карта дня — бесплатно',callback_data:'tarot:day'}],[button('Три карты — 5 ✨','buy')],[button('Последний расклад — бесплатно','tarot:last')]]);
  if(page==='buy') {
    const mid=q?.message?.message_id;
    if(!Number.isSafeInteger(mid) || mid<1) return screen(env,id,"Предложение недоступно","Откройте новое предложение в разделе «Таро». У этого сообщения нет действующего номера; списание не выполнено.",[],'tarot');
    return screen(env,id,'Подтверждение расклада',"Стоимость нового расклада: 3 ✨. Три разных Старших аркана займут позиции ситуации, препятствия и рекомендации. Текст сохраняется для повторного чтения.\n\nЕсли предыдущий оплаченный результат ещё не доставлен, сначала будет восстановлена та же запись без новой оплаты.",[[button('Подтвердить — 3 ✨',`pay:${mid}`)]],'tarot');
  }
  const pay=/^pay:([1-9][0-9]{0,15})$/.exec(page);
  if(pay && Number.isSafeInteger(Number(pay[1]))) return threeCards(shellEnv(env,'tarot'),id,pay[1]);
