    "sql": "CREATE TRIGGER astra_tarot31_erase AFTER DELETE ON astra_users BEGIN\n DELETE FROM astra_tarot31_intents WHERE telegram_id=OLD.telegram_id;\n DELETE FROM astra_tarot31_receipts WHERE telegram_id=OLD.telegram_id;\n DELETE FROM astra_tarot31_burst WHERE telegram_id=OLD.telegram_id;\nEND"
