// Compatibility exports use the immutable structural v1 reader.
const validateSnapshot=readV1,serializeSnapshot=serializeV1,parseSnapshot=parseV1,renderSnapshot=renderV1;
const {splitTelegram}=require("src/tarot25/text29.mjs");

Object.assign(module.exports,{ENGINE_VERSION,MAX_QUESTION,MAX_TEXT,SNAPSHOT_VERSION,createReading,cryptoUint32,drawCards,interpretDraw,parseSnapshot,renderSnapshot,seededRng,serializeSnapshot,splitTelegram,uniformIndex,validateCatalog,validateDraw,validateSnapshot});
