const t25Scope=t25Modules.require('src/tarot25/runtime05.mjs').scope25;
async function home25(env,id){const u=await getUser(env,id);if(!u?.zodiac)return send(env,id,'Профиль изменился. Откройте /start, чтобы продолжить.');return send(env,id,'Астра\n'+zodiacName(u.zodiac)+' · '+u.balance+' ✨\n\nВыберите, к чему обратиться сегодня.',{reply_markup:keyboard});}
async function privacy04(env,id){const result=await pre30_privacy04(env,id);if(POLICY_TRUE(env.ASTRA_TAROT25_INDEPENDENT_TEST_MODE))return send(env,id,'Таро: независимые вопросы\n\nЛичный вопрос необязателен и сохраняется только после отдельного согласия. До оплаты заказ содержит закрытый seed и настройки; текст создаётся при подтверждении. Неоплаченные данные удаляются после срока заказа и24 часов отдельной очисткой. Без её работы физическое удаление задерживается. Купленное хранится до /delete. Компактное доказательство запросов живёт вместе с профилем: старая кнопка после очистки не создаёт новую покупку.\n\nСуточного лимита оплаченных раскладов нет. Есть ограничение открытых заказов и кратковременная защита от спама; эти данные удаляются вместе с профилем. Бонусная HMAC-защита30 дней и правила платёжных записей не менялись.');return result;}
