async function incoming(env,m,updateId){if(POLICY_TRUE(env.ASTRA_TAROT25_QUESTIONS_TEST_MODE)&&m.chat?.type==='private'&&m.chat.id===m.from?.id&&!m.from?.is_bot&&typeof m.text==='string'&&!m.text.trimStart().startsWith('/')&&m.text.trim().toLowerCase()!=='gpt6'&&!MAIN_SECTIONS.some(([label])=>label===m.text.trim())&&!['Главное меню','Назад','🔮 Гороскоп','🎁 Бонус дня','✨ Баланс','👥 Пригласить друга','🌟 Канал','🔔 Рассылка','⚙️ Помощь'].includes(m.text.trim())){const u=await getUser(env,m.from.id);if(u?.zodiac&&await t25Ui.message(env,m.from.id,m.text,updateId))return;}return pre25_incoming(env,m,updateId);}
