async function callback(env,q,updateId){if(String(q.data||'').startsWith('t25:')||String(q.data||'').startsWith('q7:'))return t25Ui.callback(env,q,updateId);return pre25_callback(env,q,updateId);}
async function health(env){const response=await pre25_health(env),state=await response.json(),s=await t25Modules.require('src/tarot25/purchases31.mjs').schema31(env);state.tarot25_schema_ready=s.ready;state.tarot25_sales_enabled=Boolean(s.ready&&s.enabled===1&&POLICY_TRUE(env.ASTRA_TAROT25_ENABLED)&&s.write_enabled===1&&POLICY_TRUE(env.ASTRA_TAROT25_STORAGE_TEST_MODE)&&s.independent_enabled===1&&POLICY_TRUE(env.ASTRA_TAROT25_INDEPENDENT_TEST_MODE));state.tarot25_manual_ready=s.ready;state.public_ready=false;state.ready=false;state.release_scope='TASK07_LOCAL_CANDIDATE';return Response.json(state,{status:503,headers:{'Cache-Control':'no-store'}});}

const astraWorker = {
  async fetch(request,env) {
    const receivedAt=performance.now();
    const u=new URL(request.url);
    if(u.pathname.startsWith('/internal/payments/')||(u.pathname==='/internal/economy/policy'||u.pathname==='/internal/economy/fence')){
      try{if(!env.ASTRA_ADMIN_KEY||request.headers.get('Authorization')!=='Bearer '+env.ASTRA_ADMIN_KEY)return new Response('Forbidden',{status:403});if(!await schemaReady(env))return new Response('D1 schema unavailable',{status:503});return await paymentsAdmin(request,env);}catch{return new Response('Administrative operation unavailable; reconcile before retry',{status:503});}
    }
    if (request.method==='GET' && u.pathname==='/')
      return new Response(`Астра ${VERSION}\nДиагностика: /health`,{
        headers:{'Content-Type':'text/plain; charset=utf-8'},
      });
    if (request.method==='POST' && u.pathname==='/internal/integrity') {
      if (!env.ASTRA_ADMIN_KEY || request.headers.get('Authorization')!==`Bearer ${env.ASTRA_ADMIN_KEY}`) return new Response('Forbidden',{status:403});
      try {
        const row=await env.DB.prepare(`SELECT count(*) AS mismatches FROM astra_users u WHERE balance<>
          (SELECT coalesce(sum(delta),0) FROM astra_wallet_ledger l WHERE l.telegram_id=u.telegram_id)`).first();
        return Response.json({mismatches:row.mismatches},{headers:{'Cache-Control':'no-store'}});
      } catch { return new Response('Integrity check unavailable',{status:503}); }
    }
    if (request.method==='GET' && u.pathname==='/health') return health(env);
    if (request.method==='GET' && u.pathname==='/activate') return activate(request,env);
    if (request.method==='POST' && u.pathname==='/telegram-webhook') {
      if (!env.ASTRA_WEBHOOK_SECRET || request.headers.get('X-Telegram-Bot-Api-Secret-Token')!==env.ASTRA_WEBHOOK_SECRET)
        return new Response('Forbidden',{status:403});
      try {
        const update=await request.json();
        if(update?.pre_checkout_query){
          if(!Number.isSafeInteger(update.update_id)||update.update_id<0)throw Error('Invalid update');
          await answerStarPrecheckout(env,update.pre_checkout_query,{ready:()=>schemaReady(env),startedAt:receivedAt});
          return new Response('OK');
        }
        if(!await schemaReady(env))return new Response('D1 schema unavailable',{status:503});
        await dispatch(env,update);return new Response('OK');
      }catch(e){console.error('Webhook processing failed');return new Response('Temporary failure',{status:500});}
    }
    return new Response('Not found',{status:404});
  },
  async scheduled(_event,env) {
    if (!env.ASTRA_BOT_TOKEN || !await schemaReady(env)) { console.error('Cron: DB or token missing'); return; }
    await broadcast(env);
  },
};

export default {
  fetch(request,env){return measureInvocation(env,'http',scoped=>astraWorker.fetch(request,t25Scope(task01Env(scoped))));},
  scheduled(event,env){return measureInvocation(env,'cron',async scoped=>{try{if(scoped.DB)await purgeFences26(scoped);}catch{console.error('Bonus fence cleanup unavailable');}return astraWorker.scheduled(event,task01Env(scoped));});}
};

